<script setup>
import { onMounted, reactive, ref } from 'vue';import api from '../services/api'
const expenses=ref([]),categories=ref([]),branches=ref([]),show=ref(false),showCategory=ref(false),category=ref(''),error=ref('');const form=reactive({branch_id:'',expense_category_id:'',amount:'',reference:'',notes:''})
const load=async()=>{const [e,c,b]=await Promise.all([api.get('/expenses'),api.get('/expense-categories'),api.get('/businesses')]);expenses.value=e.data.data.data;categories.value=c.data.data;const business=b.data.data[0];if(business)branches.value=(await api.get(`/businesses/${business.id}/branches`)).data.data};onMounted(load);const addCategory=async()=>{await api.post('/expense-categories',{name:category.value});category.value='';showCategory.value=false;load()};const save=async()=>{try{await api.post('/expenses',form);show.value=false;Object.assign(form,{branch_id:'',expense_category_id:'',amount:'',reference:'',notes:''});load()}catch(e){error.value=e.response?.data?.message||'খরচ সংরক্ষণ করা যায়নি।'}};const approve=async e=>{try{await api.post(`/expenses/${e.id}/approve`);load()}catch(x){error.value=x.response?.data?.message||'অনুমোদন করা যায়নি।'}}
</script><template><section><div class="page-heading inline"><div><p class="eyebrow">EXPENSE CONTROL</p><h2>খরচ ব্যবস্থাপনা</h2><p>দৈনিক ও শাখাভিত্তিক খরচ নথিভুক্ত এবং অনুমোদন করুন।</p></div><div class="button-row"><button class="secondary" @click="showCategory=true">+ ক্যাটাগরি</button><button class="primary" @click="show=true">+ খরচ যোগ করুন</button></div></div><p v-if="error" class="error">{{error}}</p><div v-if="showCategory" class="page-card compact"><form class="inline-form" @submit.prevent="addCategory"><strong>খরচের ক্যাটাগরি</strong><input v-model="category" required /><button class="primary">সংরক্ষণ</button></form></div><div v-if="show" class="page-card compact"><form class="form-grid" @submit.prevent="save"><label>শাখা<select v-model="form.branch_id" required><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label><label>ক্যাটাগরি<select v-model="form.expense_category_id" required><option v-for="c in categories" :value="c.id">{{c.name}}</option></select></label><label>পরিমাণ<input v-model.number="form.amount" type="number" min="1" required /></label><label>রেফারেন্স<input v-model="form.reference" /></label><label class="full-width">নোট<textarea v-model="form.notes"></textarea></label><div class="full-width form-actions"><button type="button" class="secondary" @click="show=false">বাতিল</button><button class="primary">খরচ সংরক্ষণ করুন</button></div></form></div><div class="table-card"><table><thead><tr><th>তারিখ</th><th>ক্যাটাগরি</th><th>শাখা</th><th>পরিমাণ</th><th>অনুমোদন</th><th></th></tr></thead><tbody><tr v-for="e in expenses" :key="e.id"><td>{{e.expense_date}}</td><td>{{e.category?.name}}</td><td>{{e.branch?.name}}</td><td>৳{{e.amount}}</td><td><span class="role-chip">{{e.approval_status}}</span></td><td><button v-if="e.approval_status==='pending'" class="secondary small" @click="approve(e)">অনুমোদন</button></td></tr></tbody></table></div></section></template>
